class FactorizeData(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_int))]

def prime_factors(n, subtransforms):
    data = FactorizeData()
    data.data = ctypes.cast(array('i', [0] * (n + 1)), ctypes.POINTER(ctypes.c_int))
    result = gsl.fftwf_init(subtransforms)
    if not result:
        raise Exception('FFTW init failed')
    factors = []
    for i in range(2, int(n ** 0.5) + 1):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    return {'factors': factors, 'num_factors': len(factors)}

def factorize(n, subtransforms):
    result = gsl.factorize([ctypes.c_int(n)], [ctypes.POINTER(ctypes.c_double)(0)] + subtransforms)
    if not result:
        raise Exception('GSL factorize failed')
    return prime_factors(result[0], subtransforms)

def main():
    n = 1000000
    subtransforms = [ctypes.POINTER(ctypes.c_double)(0), ctypes.POINTER(ctypes.c_double)(0)]
    try:
        result = factorize(n, subtransforms)
    except Exception as e:
        print(str(e))
        return {'Candidate_solution': 'Error'}
    return {'Candidate_solution': dumps(result)}

if __name__ == '__main__':
    main()

