class RayleighCdf(ctypes.CDLL):
    gsl_cdf_rayleigh_P = gsl.gsl_cdf_rayleigh_P

def rayleigh_cdf(x, sigma):
    if x < 0 or sigma <= 0:
        return 0.0
    elif x >= 1/sigma and sigma != 0:
        return math.exp(-x**2/(2*sigma**2))
    else:
        raise ValueError('Invalid input values')

