class Combination:
    def __init__(self, n, k):
        self.n = n
        self.k = k
        self.combination_ptr = gsl.gsl_combination_alloc(n)
        if self.combination_ptr == None:
            raise ValueError('Allocation failed')
        self.init_first()
    def init_first(self):
        gsl.gsl_combination_init_first(self.combination_ptr, self.k)

    def get_combination(self):
        data = [0]*self.n
        for i in range(self.k):
            index = int(gsl.gsl_combination_get(self.combination_ptr, i))
            data[index] = 1
        return data

def create_first_combination(n, k):
    combination = Combination(n, k)
    return combination.get_combination()

