    v = libgsl.gsl_vector_alloc(N)
    w = libgsl.gsl_vector_alloc(N)

    for i in range(N):
        if i % N_sigma[0] == 0:
            sigma_val = float(sigma[0])
        elif i % N_sigma[1] == 0:
            sigma_val = float(sigma[1])
        else:
            sigma_val = float(sigma[2])

        libgsl.gsl_vector_set(v, i, norm.rvs(0, sigma_val))

    libgslcblas.gsl_cdf_gaussian_kurtosis_test(libgsl.gsl_vector_get_data(v, N), N)

    stats = [None] * K
    for i in range(K):
        libgsl.gsl_vector_set(w, i, 0.0)
        for j in range(N):
            if j < K:
                libgsl.gsl_vector_set_add(libgsl.gsl_vector_get_data(v, j), N, libgsl.gsl_vector_get(w, (j-1) % K))
            else:
                libgsl.gsl_vector_set_add(libgsl.gsl_vector_get_data(v, j), N, 0.0)
