    _type_ = gsl.filter_impulse_workspace_t
    def __init__(self):
        self.contents = gsl.filter_impulse_workspace_t(0)

def filter_impulse(n, k, t, noise_rate=0.1, outlier_rate=0.05):
    # Allocate GSL workspaces and vectors
    w = GSLFilterImpulseWorkspace()
    data = GSLVector(n)
    weights = GSLVector(k+1)
    outliers = GSLVectorInt(0)

    # Generate signal with Gaussian noise and occasional outliers
    np.random.seed(42)  # For reproducibility
