    _fields_ = [("n", c_int),
               ("x", ctypes.POINTER(c_double)),
               ("y", ctypes.POINTER(c_double)),
               ("data", ctypes.POINTER(c_double))]

def create_histogram2d(nx, ny, xrange, yrange):
    if not isinstance(nx, int) or nx <= 0:
        raise ValueError('nx must be a positive integer')
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError('ny must be a positive integer')
    if not all(isinstance(x, c_double) for x in xrange):
        raise ValueError('xrange must be a list of doubles')
    if not all(isinstance(y, c_double) for y in yrange):
        raise ValueError('yrange must be a list of doubles')
    if not all(x <= y for x, y in zip(xrange, xrange[1:])):
        raise ValueError('xrange must be increasing order')
    if not all(x <= y for x, y in zip(yrange, yrange[1:])):
        raise ValueError('yrange must be increasing order')

    gsl_histogram2d = GSL_Histogram2D()
    gsl_histogram2d.n = c_int(nx)
    gsl_histogram2d.x = ctypes.c_double * nx
    for i in range(nx):
        gsl_histogram2d.x[i] = xrange[i]
    gsl_histogram2d.y = ctypes.c_double * ny
    for i in range(ny):
        gsl_histogram2d.y[i] = yrange[i]

    return gsl_histogram2d

